/**
 * Guild / officer / parley chat view.
 *
 * Renders authored bubbles, system lines, and the deliberately humiliating
 * triple-zero broadcast (GDD §7.2 — "broadcast to their guild chat as a system
 * message so everyone knows exactly how unlucky their friend is").
 */
import { GUILD_COLORS } from '../../config/visual';
import { hashString } from '../../game/rng';
import type { ChatKind, ChatMessage, PlayerId } from '../../game/types';
import { clear, cssHex, el, fmtClock, svg as svgEl } from '../dom';
import { ICONS } from './button';
import { emptyState } from './panel';

export interface ChatViewOpts {
  onSend: (text: string) => void;
  placeholder?: string;
  /** Hard cap on input length. Defaults to 400. */
  maxLength?: number;
  /** Hide the composer (read-only archives). */
  readOnly?: boolean;
}

/** Deterministic author tint so the same commander is always the same colour. */
function authorColor(id: PlayerId): string {
  const palette = GUILD_COLORS;
  return cssHex(palette[hashString(id) % palette.length]);
}

const BUBBLE_CLASS: Record<ChatKind, string> = {
  text: '',
  system: 'msg--sys',
  triple_zero: 'msg--sys msg--zero',
  alert: 'msg--sys msg--alert',
  ping: 'msg--sys msg--ping',
  trade: 'msg--sys msg--trade',
  treaty: 'msg--sys msg--treaty',
};

function dayKey(at: number): string {
  const d = new Date(at);
  return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
}

function dayLabel(at: number, now: number): string {
  const a = new Date(at);
  const n = new Date(now);
  const sameDay = dayKey(at) === dayKey(now);
  if (sameDay) return 'TODAY';
  const yesterday = new Date(n.getFullYear(), n.getMonth(), n.getDate() - 1);
  if (dayKey(at) === dayKey(yesterday.getTime())) return 'YESTERDAY';
  return a.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }).toUpperCase();
}

export class ChatView {
  readonly el: HTMLElement;

  private readonly log: HTMLElement;
  private readonly box: HTMLTextAreaElement;
  private readonly sendBtn: HTMLButtonElement;
  private readonly opts: ChatViewOpts;
  private readonly onViewport = (): void => this.syncKeyboard();

  private pinnedToEnd = true;

  constructor(opts: ChatViewOpts) {
    this.opts = opts;
    this.log = el('div', { class: 'chat__log', attrs: { role: 'log' }, aria: { live: 'polite' } });

    this.box = el('textarea', {
      class: 'chat__box',
      attrs: {
        rows: 1,
        maxlength: opts.maxLength ?? 400,
        placeholder: opts.placeholder ?? 'TRANSMIT…',
        enterkeyhint: 'send',
        autocapitalize: 'sentences',
      },
    });

    this.sendBtn = el('button', {
      class: 'chat__send',
      attrs: { type: 'button', disabled: true },
      aria: { label: 'send' },
    });
    this.sendBtn.appendChild(svgEl(ICONS.send));

    const composer = el('div', { class: 'chat__input' }, this.box, this.sendBtn);

    this.el = el('div', { class: 'chat' }, this.log);
    if (!opts.readOnly) this.el.appendChild(composer);

    const target: HTMLElement = this.box;
    target.addEventListener('input', () => {
      this.autoGrow();
      this.sendBtn.disabled = this.box.value.trim().length === 0;
    });
    target.addEventListener('keydown', (ev: KeyboardEvent) => {
      if (ev.key === 'Enter' && !ev.shiftKey) {
        ev.preventDefault();
        this.send();
      }
    });
    target.addEventListener('focus', () => {
      window.setTimeout(() => this.scrollToEnd(), 220);
    });

    this.sendBtn.addEventListener('click', () => this.send());

    this.log.addEventListener('scroll', () => {
      const gap = this.log.scrollHeight - this.log.scrollTop - this.log.clientHeight;
      this.pinnedToEnd = gap < 60;
    });

    window.visualViewport?.addEventListener('resize', this.onViewport);
    window.visualViewport?.addEventListener('scroll', this.onViewport);
  }

  /** Replaces the transcript. Keeps the reader pinned to the bottom if they were. */
  setMessages(msgs: ChatMessage[], meId: string): void {
    const wasPinned = this.pinnedToEnd;
    clear(this.log);

    if (msgs.length === 0) {
      const empty = emptyState('⌁', 'no transmissions on this channel');
      empty.classList.add('chat__empty');
      this.log.appendChild(empty);
      return;
    }

    const now = Date.now();
    let lastDay = '';
    let lastAuthor = '';

    for (const msg of msgs) {
      const key = dayKey(msg.at);
      if (key !== lastDay) {
        lastDay = key;
        lastAuthor = '';
        this.log.appendChild(el('div', { class: 'chat__day', text: dayLabel(msg.at, now) }));
      }

      const mine = msg.authorId === meId && msg.kind === 'text';
      const kindClass = BUBBLE_CLASS[msg.kind] ?? '';
      const classes = ['msg'];
      if (mine) classes.push('msg--me');
      if (kindClass) classes.push(kindClass);

      const wrap = el('div', {
        class: classes.join(' '),
        style: msg.kind === 'text' ? `--author:${authorColor(msg.authorId)}` : undefined,
      });

      const isSystem = msg.kind !== 'text';
      const showMeta = !isSystem && (mine || msg.authorId !== lastAuthor);
      if (showMeta) {
        wrap.appendChild(
          el(
            'div',
            { class: 'msg__meta' },
            el('span', { class: 'msg__author', text: mine ? 'YOU' : msg.authorName }),
            el('span', { class: 'msg__time', text: fmtClock(msg.at) }),
          ),
        );
      }

      wrap.appendChild(el('div', { class: 'msg__bubble', text: msg.text }));
      this.log.appendChild(wrap);
      lastAuthor = isSystem ? '' : msg.authorId;
    }

    if (wasPinned) requestAnimationFrame(() => this.scrollToEnd());
  }

  scrollToEnd(): void {
    this.log.scrollTop = this.log.scrollHeight;
    this.pinnedToEnd = true;
  }

  /** Focus the composer (used when a screen opens straight into chat). */
  focusInput(): void {
    this.box.focus();
  }

  dispose(): void {
    window.visualViewport?.removeEventListener('resize', this.onViewport);
    window.visualViewport?.removeEventListener('scroll', this.onViewport);
  }

  // ── internals ─────────────────────────────────────────────────────────────

  private send(): void {
    const text = this.box.value.trim();
    if (text.length === 0) return;
    this.box.value = '';
    this.sendBtn.disabled = true;
    this.autoGrow();
    this.pinnedToEnd = true;
    this.opts.onSend(text);
  }

  private autoGrow(): void {
    this.box.style.height = 'auto';
    this.box.style.height = `${Math.min(110, this.box.scrollHeight)}px`;
  }

  /**
   * The app shell is position:fixed, so an on-screen keyboard shrinks the
   * visual viewport without reflowing layout. Pad the composer by the overlap
   * so it stays above the keyboard instead of underneath it.
   */
  private syncKeyboard(): void {
    const vv = window.visualViewport;
    if (!vv) return;
    const overlap = Math.max(0, window.innerHeight - vv.height - vv.offsetTop);
    this.el.style.paddingBottom = overlap > 24 ? `${Math.round(overlap)}px` : '';
    if (this.pinnedToEnd) this.scrollToEnd();
  }
}
